//! Embed Ren's FilmCraft fork-patch series into the adapter.
//!
//! The runtime CLI install (`src/lib.rs`) clones the pinned upstream
//! revision and replays `library/tools/upstream_patches/filmcraft/*.patch`
//! in sorted order, exactly like the local-CI intake does. The patch
//! bytes are embedded here so the install works from the compiled
//! adapter alone - never from a checkout path that a disposed worktree
//! could leave dangling. The generated file also bakes
//! `FILMCRAFT_PATCH_SET_KEY`: the FNV-1a/64 key over the series that
//! names the digest-keyed install cache. The algorithm MUST match
//! `library/tools/filmcraft_patches.py::patch_set_key` byte for byte
//! (sorted names; each feeds name bytes, one `\n`, then raw bytes),
//! pinned by a golden test on each side.

use std::env;
use std::fs;
use std::path::PathBuf;

const FNV_OFFSET_BASIS: u64 = 14695981039346656037;
const FNV_PRIME: u64 = 1099511628211;

fn fnv1a_64(feeds: &[Vec<u8>]) -> u64 {
    let mut digest = FNV_OFFSET_BASIS;
    for feed in feeds {
        for byte in feed {
            digest ^= u64::from(*byte);
            digest = digest.wrapping_mul(FNV_PRIME);
        }
    }
    digest
}

fn escape_byte_string(bytes: &[u8], out: &mut String) {
    out.push_str("b\"");
    for byte in bytes {
        match byte {
            b'\\' => out.push_str("\\\\"),
            b'"' => out.push_str("\\\""),
            0x20..=0x7E => out.push(*byte as char),
            other => out.push_str(&format!("\\x{other:02x}")),
        }
    }
    out.push('"');
}

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("set by cargo"));
    let patch_dir = manifest
        .join("../../library/tools/upstream_patches/filmcraft")
        .canonicalize()
        .expect("upstream patch directory is committed beside native/");
    println!("cargo:rerun-if-changed={}", patch_dir.display());
    let mut entries: Vec<(String, Vec<u8>)> = Vec::new();
    let mut dir = fs::read_dir(&patch_dir).expect("read upstream patch directory");
    let mut names: Vec<String> = Vec::new();
    while let Some(entry) = dir.next().transpose().expect("list patch files") {
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.ends_with(".patch") {
            println!("cargo:rerun-if-changed={}", entry.path().display());
            names.push(name);
        }
    }
    names.sort();
    for name in &names {
        let bytes = fs::read(patch_dir.join(name)).expect("read upstream patch");
        entries.push((name.clone(), bytes));
    }
    // The key feeds exactly what the Python helper feeds: each sorted
    // file name, one `\n` byte, then the raw file bytes.
    let mut feeds: Vec<Vec<u8>> = Vec::with_capacity(entries.len());
    for (name, bytes) in &entries {
        let mut feed = name.as_bytes().to_vec();
        feed.push(b'\n');
        feed.extend_from_slice(bytes);
        feeds.push(feed);
    }
    let key = fnv1a_64(&feeds);

    let mut generated = String::from(
        "// Generated by `native/ren-filmcraft/build.rs`: the embedded fork-patch\n\
         // series and its cache key. Do not edit; it regenerates every build.\n\
         #[allow(dead_code)]\n",
    );
    generated.push_str(&format!(
        "pub const FILMCRAFT_PATCH_SET_KEY: &str = \"{key:016x}\";\n\
         /// `(file name, raw patch bytes)` in replay order.\n\
         #[allow(dead_code)]\n\
         pub const FILMCRAFT_PATCHES: &[(&str, &[u8])] = &[\n"
    ));
    for (name, bytes) in &entries {
        generated.push_str("    (\"");
        generated.push_str(&name.replace('\\', "\\\\").replace('"', "\\\""));
        generated.push_str("\", ");
        escape_byte_string(bytes, &mut generated);
        generated.push_str("),\n");
    }
    generated.push_str("];\n");
    let out =
        PathBuf::from(env::var("OUT_DIR").expect("set by cargo")).join("filmcraft_patches.rs");
    fs::write(&out, generated).expect("write generated patch table");
}
